public class Main {
    static int highest(int[] marks) {
        int best = marks[0];
        for (int m : marks) {
            if (m > best) {
                best = m;
            }
        }
        return best;
    }

    public static void main(String[] args) {
        System.out.println(highest(new int[]{64, 91, 78}));
    }
}

