import java.util.Arrays;

public class Main {
    static int[] rowTotals(int[][] marks) {
        int[] totals = new int[marks.length];
        for (int r = 0; r < marks.length; r++) {
            for (int c = 0; c < marks[r].length; c++) {
                totals[r] += marks[r][c];
            }
        }
        return totals;
    }

    public static void main(String[] args) {
        System.out.println(Arrays.toString(rowTotals(new int[][]{{1, 2}, {3, 4}})));
    }
}

