public class Main {
    static String initials(String fullName) {
        return "";
    }

    public static void main(String[] args) {
        System.out.println(initials("ravi kumar"));
    }
}

task.solution:
public class Main {
    static String initials(String fullName) {
        StringBuilder sb = new StringBuilder();
        for (String w : fullName.trim().split("\\s+")) {
            sb.append(Character.toUpperCase(w.charAt(0))).append(".");
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(initials("ravi kumar") + " " + initials("  sita devi rao "));
    }
}

