project.solution:
public class Main {
    static String report(String data) {
        String top = "";
        int best = -1;
        int total = 0;
        int count = 0;
        for (String rec : data.split(",")) {
            String[] f = rec.split(":");
            int mark = Integer.parseInt(f[1]);
            total += mark;
            count++;
            if (mark > best) {
                best = mark;
                top = f[0];
            }
        }
        return "Top: " + top + " (" + best + "), Average: " + String.format("%.2f", (double) total / count);
    }

    public static void main(String[] args) {
        System.out.println(report("Ravi:72,Sita:91,Anu:64"));
    }
}
